import type { HTMLAttributes } from 'vue';

export interface WebThreadsProps {
  /** Gradient across the threads, from the first thread to the last. Up to six colors. */
  colors?: string[];
  /** Hot color where threads overlap and converge. */
  coreColor?: string;
  /** Fills the canvas behind the threads. `transparent` lets the page show through. */
  backgroundColor?: string;
  /** Draws crisp ink strokes for light backgrounds instead of glowing light. */
  lightMode?: boolean;
  /** Number of threads, up to 24. */
  threadCount?: number;
  /** How fast the threads weave. */
  speed?: number;
  /** How many waves fit across the width. */
  frequency?: number;
  /** How far the threads fan away from the pinch. */
  spread?: number;
  /** How much wider each next thread swings. */
  taper?: number;
  /** Height of the weave, from bottom 0 to top 1. */
  position?: number;
  /** Where the threads converge across the width, from 0 to 1. */
  pinch?: number;
  /** Number of pinch points. More than one braids the threads. */
  nodes?: number;
  /** Rotation of the whole weave in degrees. */
  angle?: number;
  /** Strength of the light around each thread. */
  glow?: number;
  /** How quickly the glow fades. Higher is tighter. */
  falloff?: number;
  /** Width of the threads. */
  thickness?: number;
  /** Overall brightness. */
  brightness?: number;
  /** Opacity of the whole effect. */
  opacity?: number;
  /** Twists the threads in 3D. */
  depth?: number;
  /** Strength of light pulses that travel along the threads. */
  pulses?: number;
  /** Weaves each side of the pinch as a mirror. */
  mirror?: boolean;
  /** Adds a gentle, uneven sway to each thread. */
  shimmer?: boolean;
  /** Fades the threads out toward both ends. */
  fade?: number;
  /** Film grain in the light. 0 turns it off. */
  grain?: number;
  /** Draws the threads in one after another when they first come into view. */
  intro?: boolean;
  /** The strand nearest the cursor lights up while the others recede. */
  mouseInteraction?: boolean;
  /** How strongly the focused strand stands out. */
  mouseStrength?: number;
  /** Clicking sends light along every thread. */
  pulseOnClick?: boolean;
  /** Freezes the weaving. */
  paused?: boolean;
  /** Maximum device pixel ratio of the canvas. */
  dpr?: number;
  class?: HTMLAttributes['class'];
}

export type WebThreadsRgb = [number, number, number];

export interface WebThreadsSurge {
  x: number;
  direction: number;
  at: number;
}

export interface WebThreadsShape {
  nodes: number;
  pinch: number;
  mirror: boolean;
  spread: number;
  shimmer: boolean;
  frequency: number;
  count: number;
  taper: number;
  position: number;
}

export interface WebThreadsSettings extends WebThreadsShape {
  palette: WebThreadsRgb[];
  core: WebThreadsRgb;
  paper: WebThreadsRgb | null;
  lightMode: boolean;
  speed: number;
  angle: number;
  glow: number;
  falloff: number;
  thickness: number;
  brightness: number;
  opacity: number;
  depth: number;
  pulses: number;
  fade: number;
  grain: number;
  intro: boolean;
  mouseInteraction: boolean;
  mouseStrength: number;
  pulseOnClick: boolean;
  paused: boolean;
  dpr: number;
}

export type WebThreadsPreset = 'aurora' | 'helix' | 'fiber' | 'ember' | 'mono';

export type WebThreadsLook = Required<
  Omit<
    WebThreadsProps,
    | 'class'
    | 'backgroundColor'
    | 'intro'
    | 'mouseInteraction'
    | 'mouseStrength'
    | 'pulseOnClick'
    | 'paused'
    | 'dpr'
  >
>;

import type { WebThreadsRgb, WebThreadsShape } from './types';

const TAU = Math.PI * 2;

export const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

const mod = (value: number, base: number) => ((value % base) + base) % base;

let probe: CanvasRenderingContext2D | null = null;

/** Resolves any CSS color to linear 0..1 RGB. Returns null for transparent. */
export function parseColor(
  value: string,
  fallback: WebThreadsRgb | null,
): WebThreadsRgb | null {
  if (value === 'transparent') return null;
  if (typeof document === 'undefined') return fallback;
  if (!probe) probe = document.createElement('canvas').getContext('2d');
  if (!probe) return fallback;
  probe.fillStyle = '#000000';
  probe.fillStyle = value;
  const text = String(probe.fillStyle);
  if (text.startsWith('#')) {
    const hex = Number.parseInt(text.slice(1), 16);
    return [
      ((hex >> 16) & 255) / 255,
      ((hex >> 8) & 255) / 255,
      (hex & 255) / 255,
    ];
  }
  const match = /rgba?\(([\d.]+),\s*([\d.]+),\s*([\d.]+)(?:,\s*([\d.]+))?/.exec(
    text,
  );
  if (!match) return fallback;
  if (match[4] !== undefined && Number(match[4]) === 0) return null;
  return [
    Number(match[1]) / 255,
    Number(match[2]) / 255,
    Number(match[3]) / 255,
  ];
}

export const staggerFor = (count: number) =>
  Math.min(0.12, 0.9 / Math.max(count - 1, 1));

/** Maps a container-relative point (y down) into the rotated thread space. */
export function toThreadSpace(
  px: number,
  py: number,
  aspect: number,
  angle: number,
): [number, number] {
  const qx = (px - 0.5) * aspect;
  const qy = 0.5 - py;
  const cos = Math.cos(angle);
  const sin = Math.sin(angle);
  return [(qx * cos + qy * sin) / aspect + 0.5, -qx * sin + qy * cos + 0.5];
}

/** CPU mirror of the shader's thread curve, used for cursor hit-testing. */
export function threadY(
  s: WebThreadsShape,
  x: number,
  index: number,
  phase: number,
  clock: number,
) {
  const lane = s.nodes <= 1 ? x - s.pinch : (x - s.pinch + 0.5) * s.nodes - 0.5;
  const side = s.mirror ? (mod(Math.floor(lane), 2) < 0.5 ? -1 : 1) : 1;
  const dx = x - s.pinch;
  const env =
    s.nodes <= 1
      ? s.spread * Math.abs(dx)
      : s.spread * 0.5 * Math.abs(Math.cos(Math.PI * s.nodes * (dx + 0.5)));
  const shimmer = s.shimmer ? Math.sin(clock * 1.7 + index * 1.3) * 0.35 : 0;
  const angle =
    x * s.frequency +
    (phase + (index * TAU) / Math.max(s.count, 1)) * side +
    shimmer;
  return s.position - env * (1 + index * s.taper) * Math.sin(angle);
}

export function compileShader(
  gl: WebGL2RenderingContext,
  type: number,
  source: string,
) {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    gl.deleteShader(shader);
    return null;
  }
  return shader;
}

export const MAX_THREADS = 24;
export const MAX_COLORS = 6;
export const MAX_SURGES = 3;
export const SURGE_SECONDS = 1.6;
export const SURGE_STAGGER = 0.05;
export const STROKE_SECONDS = 1.25;

export const UNIFORMS = [
  'uResolution',
  'uPhase',
  'uClock',
  'uCount',
  'uFrequency',
  'uSpread',
  'uTaper',
  'uPosition',
  'uPinch',
  'uNodes',
  'uAngle',
  'uGlow',
  'uFalloff',
  'uThickness',
  'uBrightness',
  'uOpacity',
  'uMirror',
  'uShimmer',
  'uDepth',
  'uPulses',
  'uFade',
  'uGrain',
  'uColors',
  'uColorCount',
  'uCore',
  'uBackground',
  'uOpaque',
  'uLight',
  'uIntro',
  'uFocus',
  'uFocusState',
  'uSurges',
] as const;

export const VERTEX = `#version 300 es
in vec2 aPosition;
void main() {
  gl_Position = vec4(aPosition, 0.0, 1.0);
}`;

export const FRAGMENT = `#version 300 es
precision highp float;
uniform vec2 uResolution;
uniform float uPhase;
uniform float uClock;
uniform int uCount;
uniform float uFrequency;
uniform float uSpread;
uniform float uTaper;
uniform float uPosition;
uniform float uPinch;
uniform float uNodes;
uniform vec2 uAngle;
uniform float uGlow;
uniform float uFalloff;
uniform float uThickness;
uniform float uBrightness;
uniform float uOpacity;
uniform float uMirror;
uniform float uShimmer;
uniform float uDepth;
uniform float uPulses;
uniform float uFade;
uniform float uGrain;
uniform vec3 uColors[${MAX_COLORS}];
uniform int uColorCount;
uniform vec3 uCore;
uniform vec3 uBackground;
uniform float uOpaque;
uniform float uLight;
uniform vec4 uIntro;
uniform float uFocus[${MAX_THREADS}];
uniform vec2 uFocusState;
uniform vec4 uSurges[${MAX_SURGES}];
out vec4 outColor;

const float PI = 3.14159265;
const float TAU = 6.28318530;

float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

float easeInOut(float t) {
  return t < 0.5 ? 4.0 * t * t * t : 1.0 - pow(-2.0 * t + 2.0, 3.0) * 0.5;
}

vec3 palette(float t) {
  if (uColorCount <= 1) return uColors[0];
  float scaled = clamp(t, 0.0, 1.0) * float(uColorCount - 1);
  int index = int(min(floor(scaled), float(uColorCount - 2)));
  return mix(uColors[index], uColors[index + 1], scaled - float(index));
}

vec2 envelope(float x) {
  float dx = x - uPinch;
  if (uNodes <= 1.0) return vec2(uSpread * abs(dx), uSpread * sign(dx));
  float k = PI * uNodes;
  float c = cos(k * (dx + 0.5));
  return vec2(uSpread * 0.5 * abs(c), -uSpread * 0.5 * k * sin(k * (dx + 0.5)) * sign(c));
}

vec2 space(vec2 p, float aspect) {
  vec2 q = (p - 0.5) * vec2(aspect, 1.0);
  q = vec2(q.x * uAngle.x + q.y * uAngle.y, -q.x * uAngle.y + q.y * uAngle.x);
  return vec2(q.x / aspect + 0.5, q.y + 0.5);
}

float hubAt(float x) {
  if (uNodes <= 1.0) return uPinch;
  float spacing = 1.0 / uNodes;
  return uPinch - 0.5 + (floor((x - uPinch + 0.5) / spacing) + 0.5) * spacing;
}

vec3 thread(float x, float i, float n) {
  float lane = uNodes <= 1.0 ? x - uPinch : (x - uPinch + 0.5) * uNodes - 0.5;
  float side = uMirror > 0.5 ? (mod(floor(lane), 2.0) < 0.5 ? -1.0 : 1.0) : 1.0;
  vec2 env = envelope(x);
  float amp = 1.0 + i * uTaper;
  float shimmer = uShimmer > 0.5 ? sin(uClock * 1.7 + i * 1.3) * 0.35 : 0.0;
  float angle = x * uFrequency + (uPhase + i * TAU / max(n, 1.0)) * side + shimmer;
  float wave = sin(angle);
  float y = uPosition - env.x * amp * wave;
  float slope = -(env.y * amp * wave + env.x * amp * cos(angle) * uFrequency);
  return vec3(y, slope, angle);
}

void main() {
  vec2 p = gl_FragCoord.xy / uResolution;
  float aspect = uResolution.x / uResolution.y;
  vec2 s = space(p, aspect);
  float x = s.x;
  float y = s.y;
  float n = float(uCount);
  float pixel = 1.0 / uResolution.y;
  float hub = hubAt(x);
  float presence = uFocusState.x;
  float settle = uFocusState.y;

  vec3 color = vec3(0.0);
  float energy = 0.0;
  float ink = 0.0;
  vec3 inkColor = vec3(0.0);

  for (int idx = 0; idx < ${MAX_THREADS}; idx++) {
    if (idx >= uCount) break;
    float i = float(idx);
    float ci = n > 1.0 ? i / (n - 1.0) : 0.0;

    float head = 2.0;
    float bead = 0.0;
    float born = 1.0;
    if (uIntro.w > 0.5) {
      float progress = clamp((uIntro.x - i * uIntro.y) / uIntro.z, 0.0, 1.0);
      head = mix(-0.06, 1.06, easeInOut(progress));
      bead = sin(PI * progress);
      born = progress > 0.0 ? smoothstep(-0.05, 0.03, head) : 0.0;
    }
    if (born <= 0.0) continue;

    bool tip = x > head;
    vec3 lead = bead > 0.0 || tip ? thread(head, i, n) : vec3(0.0);
    vec3 t = tip ? lead : thread(x, i, n);

    float focus = uFocus[idx];
    float spot = tip ? head : x;
    float twist = uDepth * smoothstep(0.0, 0.07, abs(spot - hubAt(spot)));
    float depth = 0.5 + 0.5 * cos(t.z);
    float front = mix(1.0, 0.3 + 0.7 * depth, twist);
    float width = uThickness * mix(1.0, 0.55 + 0.7 * depth, twist) * (1.0 + 0.3 * focus * presence);

    float d;
    if (tip) {
      float back = head - 0.02;
      vec2 a = vec2(back * aspect, thread(back, i, n).x);
      vec2 b = vec2(head * aspect, lead.x);
      vec2 pa = vec2(x * aspect, y) - a;
      vec2 ba = b - a;
      d = length(pa - ba * clamp(dot(pa, ba) / max(dot(ba, ba), 1e-6), 0.0, 1.0));
    } else {
      float bend = t.y * smoothstep(0.0, 0.04, abs(x - hub));
      d = abs(y - t.x) / sqrt(1.0 + bend * bend / (aspect * aspect));
    }
    float g = uGlow / pow(max(d / width, pixel * 0.35), uFalloff) * front * born;
    float onLine = exp(-d / (width * 0.012));

    if (bead > 0.0) {
      vec2 near = vec2((x - head) * aspect, y - lead.x);
      g *= 1.0 + bead * 1.6 * exp(-dot(near, near) / 0.0025);
    }

    float light = 0.0;
    for (int k = 0; k < ${MAX_SURGES}; k++) {
      vec4 surge = uSurges[k];
      if (surge.w <= 0.0) continue;
      float progress = clamp((surge.y - i * ${SURGE_STAGGER.toFixed(3)}) / ${SURGE_SECONDS.toFixed(2)}, 0.0, 1.0);
      if (progress <= 0.0 || progress >= 1.0) continue;
      float lead = mix(surge.x, surge.z > 0.0 ? 1.12 : -0.12, easeInOut(progress));
      float along = (x - lead) * surge.z * aspect;
      float trail = along < 0.0 ? exp(along / 0.24) : exp(-along * along / 0.0009);
      light += trail * sin(PI * progress);
    }
    g *= 1.0 + light * (0.12 + 2.8 * onLine);

    if (uPulses > 0.0) {
      float travel = abs(x - hub);
      float pulse = pow(0.5 + 0.5 * sin(travel * 16.0 + uClock * 2.2 + i * 1.9), 24.0);
      g *= 1.0 + uPulses * 5.0 * pulse * onLine;
    }

    float sheen = pow(0.5 + 0.5 * sin(abs(x - hub) * 11.0 + uClock * 1.4), 10.0);
    float lift = focus * presence;
    g *= (1.0 - settle * (1.0 - focus)) * (1.0 + lift * (0.9 + 1.4 * sheen * onLine));

    vec3 tint = mix(palette(ci), uCore, 0.3 * lift);
    color += g * tint;
    energy += g;
    float stroke = smoothstep(0.45, 1.3, g);
    inkColor += tint * stroke;
    ink += stroke;
  }

  float fade = 1.0;
  if (uFade > 0.0) {
    float edge = min(x, 1.0 - x);
    float f = clamp(edge / max(uFade * 0.5, 0.001), 0.0, 1.0);
    fade = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  }
  float core = smoothstep(0.5, 2.2, energy);
  color = mix(color, uCore * energy, core * 0.5);
  color *= uBrightness * fade;
  float alpha = clamp(energy * fade, 0.0, 1.0) * uOpacity;
  float grain = (hash(gl_FragCoord.xy + fract(uClock) * 97.0) - 0.5) * uGrain;

  if (uLight < 0.5) {
    vec3 rgb = max(color * alpha * (1.0 + grain * 2.0), 0.0);
    if (uOpaque > 0.5) {
      outColor = vec4(min(uBackground * (1.0 - alpha) + rgb, 1.0), 1.0);
    } else {
      outColor = vec4(rgb, alpha);
    }
  } else {
    ink *= fade;
    vec3 hue = ink > 0.0001 ? inkColor / ink : palette(0.5);
    float body = clamp(ink, 0.0, 1.0);
    float haze = clamp(1.0 - exp(-energy * fade * 0.3), 0.0, 1.0) * 0.12;
    float focal = smoothstep(2.0, 9.0, energy * fade) * 0.25;
    float cover = clamp((body * 0.9 + (haze + focal) * (1.0 - body)) * (1.0 + grain * 2.0), 0.0, 0.95) * uOpacity;
    vec3 stroke = hue;
    if (uOpaque > 0.5) {
      outColor = vec4(mix(uBackground, stroke, cover), 1.0);
    } else {
      outColor = vec4(stroke * cover, cover);
    }
  }
}`;
